import{_ as i,l,o as e,c as o,v as t,p as n,x as r,d as S,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"RSS 与多队列网卡","description":"","frontmatter":{"title":"RSS 与多队列网卡","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rss-multiqueue.md","filePath":"cs/rss-multiqueue.md","lastUpdated":1789023840000}'),c={name:"cs/rss-multiqueue.md"};function h(u,a,P,R,_,m){const s=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="rss-与多队列网卡" tabindex="-1">RSS 与多队列网卡 <a class="header-anchor" href="#rss-与多队列网卡" aria-label="Permalink to &quot;RSS 与多队列网卡&quot;">​</a></h1><div class="epigraph"><p>RSS 用包头哈希选择接收队列，每队列绑不同 CPU 的 NAPI，使多流并行而不在单核 livelock。</p><footer>—— 据 Microsoft RSS 白皮书直觉；Linux 对 indirection table 与 XPS 的文档</footer></div><p><a href="/cs/napi">NAPI</a> 每队列一份。<a href="/cs/dpdk-kernel-bypass">DPDK</a> 也按队列绑核。缺口是 <strong>RSS</strong>：硬件把流散开，以及 XPS 在发送侧对称。不是存储 mq 的复制粘贴——哈希对象是五元组。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单队列：万兆一根 NAPI 打满一核。RSS：NIC 算 hash，查间接表得队列号，MSI-X 到对应 CPU。缺口：哈希不对称则转发方向换核，缓存冷；对称 RSS 或 Toeplitz 密钥配置；RPS 是无 RSS 硬件时的软件 steer。本课不把每一家 ethtool 字段当作业。</p><p><span class="marginnote">Flow Director / aRFS 可把已有套接字所在核告诉网卡。XPS：发送队列按 CPU 选，减少跨核锁。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>初始化：建 N 对 RX/TX 队列，设间接表。运行：同五元组进同队列，TCP 同流有序。对照 <a href="/cs/blk-schedulers">blk-mq</a>：blk-mq 按提交者 CPU；RSS 按包头，与提交者无关。对照 netns：每设备自己的队列，veth 软件哈希另说。</p>',8)),(e(),n(p,null,{default:r(()=>[d(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PKT%5B%22%E5%85%A5%E5%8C%85%22%5D%20--%3E%20HASH%5B%22RSS%20%E5%93%88%E5%B8%8C%22%5D%0A%20%20HASH%20--%3E%20LUT%5B%22%E9%97%B4%E6%8E%A5%E8%A1%A8%22%5D%0A%20%20LUT%20--%3E%20Q%5B%22RX%20%E9%98%9F%E5%88%97%22%5D%0A%20%20Q%20--%3E%20CPU%5B%22%E5%AF%B9%E5%BA%94%20CPU%20%E7%9A%84%20NAPI%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[S(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>RSS 把并行从「更多中断」变成「更多队列」，是多核网络的默认几何。它不保证应用线程在同一核——还要 RFS 或用户绑核。不要写成量化分片。与 <a href="/cs/gro-gso">GRO</a>：GRO 在单队列内合并，跨队列不能拼同一流（同流本应同队列）。</p><p>重配置队列数会扰动亲和，生产上要谨慎。</p><p>实现上：间接表可把部分队列置零以离线 CPU。对称哈希让转发五元组双向同队列。隧道封装后若只哈希外层，内层流会撞同一队列。 读法上只引用<a href="/cs/dpdk-kernel-bypass">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「网络栈 / 收发路径」课序里，对象是 <strong>RSS 与多队列网卡</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 infiniband 的 RQ 与 CQ 命名（RDMA 后课）。不保证隧道封装后内层哈希（RSS 可能只看外层）。下一课把拷贝再削：零拷贝网络。</p><p>版本字段会变，课序钉的是机制对象「RSS 与多队列网卡」，不是某一主线内核的结构体名。 后课默认：多队列靠 RSS 散列到 CPU。发送/接收少拷贝的机制，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RSS 按流哈希选 RX 队列并绑 CPU。</li><li>XPS/RFS 补发送与应用核亲和。</li><li>零拷贝网络是下一课。</li><li>出处：RSS 文献；Linux networking；ethtool 队列。</li></ul>',11))])}const T=i(c,[["render",h]]);export{A as __pageData,T as default};
